/** Every method: params, result, owning crate, and whether it streams. */
export interface Methods {
  "bevy-ts/hello": { params: undefined; result: HelloResult; crate: "bevy-ts-remote"; watch: false };
  "bevy-ts/discover": { params: undefined; result: OpenRpcDocument; crate: "bevy-ts-remote"; watch: false };
  "bevy-ts/reload": { params: ReloadParams | undefined; result: ReloadReport; crate: "bevy-ts-remote"; watch: false };
  "bevy-ts/reload+watch": { params: undefined; result: ReloadWatchMessage; crate: "bevy-ts-remote"; watch: true };
  "bevy-ts/schema": { params: SchemaParams | undefined; result: SchemaResult; crate: "bevy-ts-remote"; watch: false };
  "bevy-ts/get_components": { params: GetComponentsParams; result: GetComponentsResult; crate: "bevy-ts-remote"; watch: false };
  "bevy-ts/get_components+watch": { params: GetComponentsParams; result: GetComponentsWatchResult; crate: "bevy-ts-remote"; watch: true };
  "bevy-ts/mutate_components": { params: MutateComponentsParams; result: null; crate: "bevy-ts-remote"; watch: false };
  "bevy-ts/pause": { params: PauseParams; result: PauseResult; crate: "bevy-ts-remote"; watch: false };
  "bevy-ts/step": { params: StepParams | undefined; result: PauseResult; crate: "bevy-ts-remote"; watch: false };
  "bevy-ts/entities": { params: undefined; result: EntitiesResult; crate: "bevy-ts-remote"; watch: false };
  "bevy-ts/entities+watch": { params: undefined; result: EntitiesWatchMessage; crate: "bevy-ts-remote"; watch: true };
  "bevy-ts/systems": { params: undefined; result: SystemsResult; crate: "bevy-ts-remote"; watch: false };
  "bevy-ts/log+watch": { params: undefined; result: LogWatchMessage; crate: "bevy-ts-remote"; watch: true };
  "bevy-ts/tsx_tree": { params: undefined; result: TsxTreeResult; crate: "bevy-ts-tsx"; watch: false };
  "bevy-ts/tsx_node": { params: TsxNodeParams; result: TsxNodeResult; crate: "bevy-ts-tsx"; watch: false };
  "bevy-ts/tsx_find": { params: TsxFindParams; result: TsxFindResult; crate: "bevy-ts-tsx"; watch: false };
  "bevy-ts/tsx_tree+watch": { params: undefined; result: TsxTreeWatchMessage; crate: "bevy-ts-tsx"; watch: true };
  "bevy-ts/viewport_attach": { params: ViewportAttachParams; result: ViewportAttachResult; crate: "bevy-ts-viewport"; watch: false };
  "bevy-ts/viewport_detach": { params: undefined; result: ViewportDetachResult; crate: "bevy-ts-viewport"; watch: false };
  "bevy-ts/viewport_resize": { params: ViewportResizeParams; result: ViewportSize; crate: "bevy-ts-viewport"; watch: false };
  "bevy-ts/viewport_input": { params: ViewportInputParams; result: ViewportInputResult; crate: "bevy-ts-viewport"; watch: false };
  "bevy-ts/viewport_mode": { params: ViewportModeParams | undefined; result: ViewportModeResult; crate: "bevy-ts-viewport"; watch: false };
  "bevy-ts/viewport_camera": { params: ViewportCameraParams | undefined; result: ViewportCamera; crate: "bevy-ts-viewport"; watch: false };
  "bevy-ts/viewport_pick": { params: ViewportPickParams; result: ViewportPickResult; crate: "bevy-ts-viewport"; watch: false };
  "bevy-ts/viewport_select": { params: ViewportSelectParams; result: ViewportSelection; crate: "bevy-ts-viewport"; watch: false };
  "bevy-ts/viewport_selection+watch": { params: undefined; result: ViewportSelection; crate: "bevy-ts-viewport"; watch: true };
  "bevy-ts/viewport_edits+watch": { params: undefined; result: ViewportEditsMessage; crate: "bevy-ts-viewport"; watch: true };
  "bevy-ts/viewport_edit_result": { params: ViewportEditResultParams; result: ViewportEdit; crate: "bevy-ts-viewport"; watch: false };
  "bevy-ts/viewport_revert": { params: ViewportRevertParams; result: ViewportEdit; crate: "bevy-ts-viewport"; watch: false };
  "bevy-ts/viewport_stats": { params: undefined; result: ViewportStats; crate: "bevy-ts-viewport"; watch: false };
  "bevy-ts/assets": { params: AssetsParams | undefined; result: AssetsResult; crate: "bevy-ts-viewport"; watch: false };
  "bevy-ts/assets+watch": { params: undefined; result: AssetsWatchMessage; crate: "bevy-ts-viewport"; watch: true };
  "bevy-ts/asset_thumbnail": { params: AssetThumbnailParams; result: AssetThumbnailResult; crate: "bevy-ts-viewport"; watch: false };
  "bevy-ts/level_list": { params: undefined; result: LevelListResult; crate: "bevy-ts-levels"; watch: false };
  "bevy-ts/level_node": { params: LevelNodeParams; result: LevelNodeResult; crate: "bevy-ts-levels"; watch: false };
  "bevy-ts/level_write": { params: LevelWriteParams; result: LevelWriteResult; crate: "bevy-ts-levels"; watch: false };
  "bevy-ts/level_apply": { params: LevelApplyParams; result: LevelApplyResult; crate: "bevy-ts-levels"; watch: false };
  "bevy-ts/level+watch": { params: undefined; result: LevelWatchMessage; crate: "bevy-ts-levels"; watch: true };
}

export type MethodName = keyof Methods;

/** Notifications on a viewport's Mach channel: params, and the side that sends each. */
export interface ChannelMessages {
  "hello": { params: Empty; from: "viewer" };
  "bye": { params: Empty; from: "viewer" };
  "input": { params: ViewportInput; from: "viewer" };
  "tick": { params: TickMessage; from: "viewer" };
  "resize": { params: ViewportResizeParams; from: "viewer" };
  "visible": { params: OnMessage; from: "viewer" };
  "focus": { params: OnMessage; from: "viewer" };
  "surface": { params: SurfaceMessage; from: "engine" };
  "frame": { params: FrameMessage; from: "engine" };
  "cursor": { params: CursorMessage; from: "engine" };
  "cursor_grab": { params: CursorGrabMessage; from: "engine" };
  "cursor_warp": { params: CursorWarpMessage; from: "engine" };
  "ime_area": { params: ImeAreaMessage; from: "engine" };
  "ime_allowed": { params: OnMessage; from: "engine" };
}
